#include <iostream>
#include <iomanip>

class Ellipsoid {
private:
    double r1, r2, r3;
    static const double PI;
public:
    // 构造函数，带默认值
    Ellipsoid(double r1 = 1.0, double r2 = 1.0, double r3 = 1.0)
        : r1(r1), r2(r2), r3(r3) {}

    // 重载==运算符
    bool operator==(const Ellipsoid &other) const {
        return (r1 == other.r1 && r2 == other.r2 && r3 == other.r3);
    }

    // 计算体积 V = 4*PI*r1*r2*r3/3
    double GetVolume() const {
        return 4.0 * PI * r1 * r2 * r3 / 3.0;
    }
};

// 类外初始化静态常量成员
const double Ellipsoid::PI = 3.1416;

int main() {
    double a1, a2, a3, b1, b2, b3;
    std::cin >> a1 >> a2 >> a3;
    std::cin >> b1 >> b2 >> b3;

    Ellipsoid e1(a1, a2, a3);
    Ellipsoid e2(b1, b2, b3);

    // 输出体积，保留3位小数
    std::cout << std::fixed << std::setprecision(3);
    std::cout << e1.GetVolume() << ", " << e2.GetVolume() << std::endl;

    // 判断是否相同
    if (e1 == e2) {
        std::cout << "The 1st ellipsoid is exactly the same as the 2nd one" << std::endl;
    } else {
        std::cout << "The 1st ellipsoid is different from the 2nd one" << std::endl;
    }

    return 0;
}

#include <iostream>

// 抽象基类
class Humanoid {
public:
    virtual void SayHello() = 0; // 纯虚函数
    virtual ~Humanoid() {}       // 虚析构函数
};

// 矮人类
class Dwarf : public Humanoid {
public:
    void SayHello() override {
        std::cout << "Hi, I am a dwarf." << std::endl;
    }
};

// 精灵类
class Elf : public Humanoid {
public:
    void SayHello() override {
        std::cout << "Hi, I am an elf." << std::endl;
    }
};

// 兽人类
class Orc : public Humanoid {
public:
    void SayHello() override {
        std::cout << "Hi, I am an orc." << std::endl;
    }
};

int main() {
    int n;
    std::cin >> n;

    // 动态分配基类指针数组
    Humanoid **arr = new Humanoid*[n];

    for (int i = 0; i < n; i++) {
        char type;
        std::cin >> type;
        if (type == 'D') {
            arr[i] = new Dwarf();
        } else if (type == 'E') {
            arr[i] = new Elf();
        } else if (type == 'O') {
            arr[i] = new Orc();
        }
    }

    // 多态调用
    for (int i = 0; i < n; i++) {
        arr[i]->SayHello();
    }

    // 释放内存
    for (int i = 0; i < n; i++) {
        delete arr[i];
    }
    delete[] arr;

    return 0;
}

#include <iostream>

class Circle {
private:
    double x, y; // 圆心坐标
    double r;    // 半径
public:
    static const double PI; // 公有静态常量

    // 构造函数，默认原点单位圆
    Circle(double x = 0.0, double y = 0.0, double r = 1.0)
        : x(x), y(y), r(r) {}

    // 计算周长
    double perimeter() const {
        return 2 * PI * r;
    }

    // 计算面积
    double area() const {
        return PI * r * r;
    }

    // 输出信息
    void print() const {
        std::cout << "Center: (" << x << ", " << y << ")" << std::endl;
        std::cout << "Radius: " << r << std::endl;
        std::cout << "Perimeter: " << perimeter() << std::endl;
        std::cout << "Area: " << area() << std::endl;
    }
};

// 类外初始化静态常量
const double Circle::PI = 3.1416;

int main() {
    double x, y, r;
    std::cin >> x >> y >> r;

    Circle c(x, y, r);
    c.print();

    return 0;
}

#include <iostream>

class Holiday {
private:
    int year, month, day;
public:
    Holiday(int y = 0, int m = 0, int d = 0)
        : year(y), month(m), day(d) {}

    // 重载 ==
    bool operator==(const Holiday &other) const {
        return year == other.year && month == other.month && day == other.day;
    }

    // 重载 >>，输入格式：年-月-日，如 1949-10-1
    friend std::istream &operator>>(std::istream &is, Holiday &h) {
        char ch1, ch2;
        is >> h.year >> ch1 >> h.month >> ch2 >> h.day;
        return is;
    }

    // 重载 <<，输出格式：年-月-日
    friend std::ostream &operator<<(std::ostream &os, const Holiday &h) {
        os << h.year << "-" << h.month << "-" << h.day;
        return os;
    }
};

int main() {
    Holiday myHoliday, partyBirthday;
    Holiday nationalDay(1949, 10, 1); // 国庆节

    std::cout << "Enter myHoliday (year-month-day): ";
    std::cin >> myHoliday;

    std::cout << "Enter partyBirthday (year-month-day): ";
    std::cin >> partyBirthday;

    std::cout << "myHoliday: " << myHoliday << std::endl;
    std::cout << "partyBirthday: " << partyBirthday << std::endl;
    std::cout << "nationalDay: " << nationalDay << std::endl;

    if (myHoliday == nationalDay) {
        std::cout << "myHoliday is National Day." << std::endl;
    } else {
        std::cout << "myHoliday is not National Day." << std::endl;
    }

    if (partyBirthday == nationalDay) {
        std::cout << "partyBirthday is National Day." << std::endl;
    } else {
        std::cout << "partyBirthday is not National Day." << std::endl;
    }

    return 0;
}

#include <iostream>
#include <string>

class Person {
protected:
    std::string szName;
public:
    Person(const std::string &name = "") : szName(name) {}

    virtual void print() const {
        std::cout << "Person " << szName << std::endl;
    }

    virtual ~Person() {}
};

class Student : public Person {
protected:
    int iNumber;
public:
    Student(const std::string &name = "", int num = 0)
        : Person(name), iNumber(num) {}

    void print() const override {
        std::cout << "Student " << szName << " " << iNumber << std::endl;
    }
};

class Graduate : public Student {
protected:
    std::string szResearch;
public:
    Graduate(const std::string &name = "", int num = 0,
             const std::string &research = "")
        : Student(name, num), szResearch(research) {}

    void print() const override {
        std::cout << "Graduate " << szName << " " << iNumber
                  << " " << szResearch << std::endl;
    }
};

int main() {
    std::string name, research;
    int number;

    // 输入Person
    std::cin >> name;
    Person *p = new Person(name);

    // 输入Student
    std::cin >> name >> number;
    Person *s = new Student(name, number);

    // 输入Graduate
    std::cin >> name >> number >> research;
    Person *g = new Graduate(name, number, research);

    // 基类指针数组
    Person *arr[3] = {p, s, g};

    // 多态调用
    for (int i = 0; i < 3; i++) {
        arr[i]->print();
    }

    // 释放内存
    for (int i = 0; i < 3; i++) {
        delete arr[i];
    }

    return 0;
}

#include <iostream>

class CFraction {
    int num; // 分子
    int den; // 分母
public:
    CFraction(int n = 0, int d = 1) : num(n), den(d) {}

    // 重载>>
    friend std::istream &operator>>(std::istream &in, CFraction &fr) {
        in >> fr.num >> fr.den;
        return in;
    }

    // 重载<<
    friend std::ostream &operator<<(std::ostream &out, const CFraction &fr) {
        out << fr.num << "/" << fr.den;
        return out;
    }

    // 重载+
    CFraction operator+(const CFraction &other) const {
        return CFraction(num * other.den + den * other.num, den * other.den);
    }

    // 重载-
    CFraction operator-(const CFraction &other) const {
        return CFraction(num * other.den - den * other.num, den * other.den);
    }

    // 重载>
    bool operator>(const CFraction &other) const {
        CFraction tmp = *this - other;
        return (tmp.num * tmp.den > 0);
    }

    // 重载<
    bool operator<(const CFraction &other) const {
        CFraction tmp = *this - other;
        return (tmp.num * tmp.den < 0);
    }
};

int main() {
    CFraction f1, f2;
    std::cin >> f1 >> f2;
    std::cout << "A+B:" << (f1 + f2) << std::endl;
    std::cout << "A-B:" << (f1 - f2) << std::endl;
    std::cout << "A>B:" << std::boolalpha << (f1 > f2) << std::endl;
    std::cout << "A<B:" << std::boolalpha << (f1 < f2) << std::endl;
    return 0;
}

