#include <iostream>

class CPoint {
    float x;
    float y;
public:
    CPoint(float _x = 0, float _y = 0) : x(_x), y(_y) {}
    friend class CCircle; // CCircle为CPoint的友元
};

class CCircle {
    CPoint center;           // 组合CPoint对象
    float radius;
    static const float PI;   // 静态常量成员
public:
    CCircle(float _x, float _y, float r)
        : center(_x, _y), radius(r) {}

    float GetRadius() const {
        return radius;
    }

    void GetCenter(float &x, float &y) const {
        x = center.x;
        y = center.y;
    }

    float GetArea() const {
        return PI * radius * radius;
    }
};

// 类外初始化静态常量
const float CCircle::PI = 3.14;

int main() {
    float x, y, r;
    std::cin >> x >> y >> r;
    CCircle c(x, y, r);

    c.GetCenter(x, y);
    std::cout << "center: (" << x << "," << y << ")" << std::endl;
    std::cout << "radius: " << c.GetRadius() << std::endl;
    std::cout << "area: " << c.GetArea() << std::endl;

    return 0;
}

