#include <iostream>

class CRectangle {
private:
    int w, h;
    static int totalNumber;   // 总个数
    static int totalArea;     // 总面积
public:
    // 带参构造函数
    CRectangle(int w, int h) : w(w), h(h) {
        totalNumber++;
        totalArea += w * h;
    }

    // 析构函数
    ~CRectangle() {
        totalNumber--;
        totalArea -= w * h;
    }

    // 静态成员函数输出统计信息
    static void PrintTotal() {
        std::cout << "totalNumber: " << totalNumber << std::endl;
        std::cout << "totalArea: " << totalArea << std::endl;
    }
};

// 类外初始化静态成员
int CRectangle::totalNumber = 0;
int CRectangle::totalArea = 0;

int main() {
    int w1, h1, w2, h2;
    std::cin >> w1 >> h1;
    std::cin >> w2 >> h2;

    CRectangle r1(w1, h1);
    CRectangle r2(w2, h2);

    CRectangle::PrintTotal();

    return 0;
}

#include <iostream>

class myComplex {
private:
    double real, imag;
public:
    myComplex(double r = 0, double i = 0) : real(r), imag(i) {}

    // 重载+
    myComplex operator+(const myComplex &other) const {
        return myComplex(real + other.real, imag + other.imag);
    }

    // 重载-
    myComplex operator-(const myComplex &other) const {
        return myComplex(real - other.real, imag - other.imag);
    }

    // 重载>>
    friend std::istream &operator>>(std::istream &is, myComplex &c) {
        is >> c.real >> c.imag;
        return is;
    }

    // 重载<<
    friend std::ostream &operator<<(std::ostream &os, const myComplex &c) {
        os << c.real;
        if (c.imag >= 0) {
            os << "+" << c.imag << "i";
        } else {
            os << c.imag << "i"; // 负号自动带出
        }
        return os;
    }
};

int main() {
    myComplex a, b;
    std::cin >> a >> b;

    myComplex sum = a + b;
    myComplex diff = a - b;

    std::cout << sum << std::endl;
    std::cout << diff << std::endl;

    return 0;
}

#include <iostream>
#include <string>

// 抽象基类
class Animal {
protected:
    std::string name;
public:
    Animal(const std::string &n = "") : name(n) {}
    virtual void talk() = 0; // 纯虚函数
    virtual ~Animal() {}
};

// 猫类
class Cat : public Animal {
public:
    Cat(const std::string &n) : Animal(n) {}
    void talk() override {
        std::cout << name << " MiaoMiao" << std::endl;
    }
};

// 狗类
class Dog : public Animal {
public:
    Dog(const std::string &n) : Animal(n) {}
    void talk() override {
        std::cout << name << " WangWang" << std::endl;
    }
};

int main() {
    int n;
    std::cin >> n;

    Animal **arr = new Animal*[n];

    for (int i = 0; i < n; i++) {
        char type;
        std::string name;
        std::cin >> type >> name;
        if (type == 'C') {
            arr[i] = new Cat(name);
        } else if (type == 'D') {
            arr[i] = new Dog(name);
        }
    }

    // 多态调用
    for (int i = 0; i < n; i++) {
        arr[i]->talk();
    }

    // 释放内存
    for (int i = 0; i < n; i++) {
        delete arr[i];
    }
    delete[] arr;

    return 0;
}

explanation:
## 1. 设计思路与要点

本题考查 C++ 面向对象程序设计中的继承、多态、抽象类、纯虚函数和虚析构函数。

题目要求设计一个动物类层次结构：

- 基类 `Animal`
  - 包含保护数据成员 `name`
  - 包含纯虚函数 `talk()`
- 派生类 `Cat`
  - 继承 `Animal`
  - 实现 `talk()`，输出：`名字 MiaoMiao`
- 派生类 `Dog`
  - 继承 `Animal`
  - 实现 `talk()`，输出：`名字 WangWang`
- 在主函数中使用 `Animal` 类型的指针保存不同派生类对象，并通过基类指针调用虚函数 `talk()`，实现运行时多态。

## 2. 抽象基类 Animal

```cpp
class Animal {
protected:
    std::string name;
public:
    Animal(const std::string &n = "") : name(n) {}
    virtual void talk() = 0;
    virtual ~Animal() {}
};
```

其中：

- `name` 使用 `protected`，使派生类可以直接访问动物名称。
- `virtual void talk() = 0;` 表示 `talk()` 是纯虚函数，因此 `Animal` 是抽象类，不能直接实例化。
- 析构函数声明为虚函数，保证通过基类指针删除派生类对象时能够正确析构。

## 3. 派生类 Cat 和 Dog

猫类实现如下：

```cpp
