// 四边形类（矩形）
class CSquare : public CShape {
private:
    double m_dWidth, m_dHeight;
public:
    CSquare(double dWidth, double dHeight)
        : m_dWidth(dWidth), m_dHeight(dHeight) {}

    double GetLength() const override {
        return 2 * (m_dWidth + m_dHeight);
    }
};

// 圆类
class CCircle : public CShape {
private:
    double m_dRadius;
    static const double PI;
public:
    CCircle(double dRadius) : m_dRadius(dRadius) {}

    double GetLength() const override {
        return 2 * PI * m_dRadius;
    }
};

const double CCircle::PI = 3.1416;

int main() {
    CSquare sq(3.0, 4.0);
    CCircle ci(5.0);

    // 基类指针实现多态
    CShape *shapes[2] = {&sq, &ci};

    for (int i = 0; i < 2; i++) {
        std::cout << "Perimeter: " << shapes[i]->GetLength() << std::endl;
    }

    return 0;
}

