// 类外定义类模板的成员函数
template <typename T>
T Data<T>::getMin() const {
    T min_val = data[0];
    for (int i = 1; i < 3; i++) {
        if (data[i] < min_val) {
            min_val = data[i];
        }
    }
    return min_val;
}

int main() {
