// 题目：protected 成员访问改错
// protected 成员：
// 1. 类外不能通过对象直接访问；
// 2. 派生类的成员函数可以访问从基类继承来的 protected 成员。

class Base {
protected:
    int value;

public:
    Base(int v = 0) : value(v) {}
};

class Derived : public Base {
public:
    Derived(int v = 0) : Base(v) {}

    void setValue(int v) {
        // 正确：派生类成员函数可以访问基类的 protected 成员
        value = v;
    }

    void showValue() const {
        cout << "value = " << value << endl;
    }
};

int main() {
    Derived d(10);

    // 错误示例：
    // d.value = 20;
    // 原因：value 是 Base 的 protected 成员，不能在类外通过对象直接访问。

    // 正确做法：通过派生类提供的 public 成员函数间接访问
    d.setValue(20);
    d.showValue();

    cout << "错误原因：protected 成员不能在类外直接访问，只能在本类、友元或派生类成员函数中访问。" << endl;

