#include <iostream>
using namespace std;

// 题目：多继承同名成员函数二义性改错
// 当多个基类中存在同名成员函数时，派生类对象直接调用该函数会产生二义性。

class Base1 {
public:
    void show() const {
        cout << "Base1::show()" << endl;
    }
};

class Base2 {
public:
    void show() const {
        cout << "Base2::show()" << endl;
    }
};

class Derived : public Base1, public Base2 {
public:
    // 解决方法 1：在派生类中重新定义同名函数，明确调用哪个基类的函数
    void show() const {
        cout << "Derived::show()" << endl;
        Base1::show();
        Base2::show();
    }
};

int main() {
    Derived d;

    // 错误示例：如果 Derived 中没有重新定义 show()，下面调用会产生二义性
    // d.show();
    // 原因：Base1 和 Base2 中都有 show()，编译器不知道调用哪一个。

    // 正确做法 1：通过作用域限定符明确指定
    d.Base1::show();
    d.Base2::show();

    // 正确做法 2：在派生类中重新定义 show()
    d.show();

    cout << "错误原因：多继承中多个基类有同名成员函数时，派生类对象直接调用会产生二义性。" << endl;

    return 0;
}

explanation:
## 1. 设计思路与要点

本题考查 C++ 多继承中同名成员函数带来的二义性问题。

在 C++ 中，一个派生类可以同时继承多个基类：

```cpp
class Derived : public Base1, public Base2 {
};
```

如果多个基类中存在同名成员函数，例如：

```cpp
class Base1 {
public:
    void show() const;
};

class Base2 {
public:
    void show() const;
};
```

那么 `Derived` 类对象中会同时拥有从 `Base1` 和 `Base2` 继承来的 `show()` 函数。

如果派生类 `Derived` 本身没有重新定义 `show()`，直接写：

```cpp
Derived d;
d.show();
```

编译器无法判断应该调用 `Base1::show()` 还是 `Base2::show()`，因此会产生成员访问二义性。

解决方法主要有两种：

### 方法一：使用作用域限定符明确指定调用哪个基类函数

```cpp
d.Base1::show();
d.Base2::show();
```

这样可以明确告诉编译器要调用哪个基类中的 `show()` 函数。

### 方法二：在派生类中重新定义同名函数

```cpp
class Derived : public Base1, public Base2 {
public:
    void show() const {
        Base1::show();
        Base2::show();
    }
};
```

此时再调用：

```cpp
d.show();
```

调用的是 `Derived::show()`，不会产生二义性。

因此，本题错误原因是：多继承时多个基类中存在同名成员函数，而派生类对象直接调用该函数时，编译器无法确定具体调用哪个基类版本。

