using namespace std;

// 抽象基类 Shape
class Shape {
public:
    virtual ~Shape() = default;

    // 纯虚函数：计算面积
    virtual double Area() const = 0;

    // 纯虚函数：显示图形信息
    virtual void Show() const = 0;
};

// 圆形类
class Circle : public Shape {
private:
    double radius;

public:
    explicit Circle(double r) : radius(r) {}

    double Area() const override {
        const double PI = acos(-1.0);
        return PI * radius * radius;
    }

    void Show() const override {
        cout << "Circle: radius = " << radius
             << ", area = " << Area() << endl;
    }
};

// 矩形类
class Rectangle : public Shape {
private:
    double length;
    double width;

public:
    Rectangle(double l, double w) : length(l), width(w) {}

    double Area() const override {
        return length * width;
    }

    void Show() const override {
        cout << "Rectangle: length = " << length
             << ", width = " << width
             << ", area = " << Area() << endl;
    }
};

int main() {
    cout << fixed << setprecision(2);

    vector<unique_ptr<Shape>> shapes;

    // 创建不同图形对象
    shapes.push_back(make_unique<Circle>(3.0));
    shapes.push_back(make_unique<Rectangle>(4.0, 5.0));
    shapes.push_back(make_unique<Circle>(2.5));
    shapes.push_back(make_unique<Rectangle>(6.0, 2.0));

    double totalArea = 0.0;

    cout << "各图形信息如下：" << endl;
    for (const auto &shape : shapes) {
        shape->Show();
        totalArea += shape->Area();
    }

    cout << "所有图形的总面积 = " << totalArea << endl;

    return 0;
}

#include <iostream>
using namespace std;

const double PI = 3.1415926;

class Shape
{
public:
    Shape() { }
    virtual ~Shape() { }
    virtual void ShowArea() = 0;
    static double totalArea;
    static void ShowTotalArea()
    {
        cout << "总面积:" << totalArea << endl;
    }
};

double Shape::totalArea = 0;

class Circle : public Shape
{
private:
    double radius;

public:
    Circle(double r) : radius(r)
    {
        totalArea += PI * r * r;
    }

    ~Circle() { }

    virtual void ShowArea()
    {
        cout << "圆面积:" << PI * radius * radius << endl;
    }
};

class Rectangle : public Shape
{
private:
    double length;
    double width;

public:
    Rectangle(double l, double w) : length(l), width(w)
    {
        totalArea += l * w;
    }

    ~Rectangle() { }

    virtual void ShowArea()
    {
        cout << "矩形面积:" << length * width << endl;
    }
};

class Square : public Shape
{
private:
    double side;

public:
    Square(double s) : side(s)
    {
        totalArea += s * s;
    }

    ~Square() { }

    virtual void ShowArea()
    {
        cout << "正方形面积:" << side * side << endl;
    }
};

int main()
{
    Shape* p[3];

    p[0] = new Circle(2.0);
    p[1] = new Rectangle(3.0, 4.0);
    p[2] = new Square(5.0);

    for (int i = 0; i < 3; ++i)
    {
        p[i]->ShowArea();
    }

    Shape::ShowTotalArea();

    for (int i = 0; i < 3; ++i)
    {
        delete p[i];
    }

    return 0;
}

